#!/usr/bin/env python3
"""Small return/phase graph generated by the kit's literal period12 tiles.

No full temporal-profile census. Reachable-node cap4096, fixed p12 only.
See GPT-PERIOD12-PHASE-RETURN-20261110.md for predictions and stage stops.
"""
import hashlib
import itertools
import json
import os
from pathlib import Path
import re
from collections import deque

P=12
FULL=(1<<P)-1
KIT_SHA='0ab24513cc18e4225e2b17bd0358a2776d387b8b21a32ff0bdb6945142bc72f3'


def rot(w,k):
    k%=P
    return ((w>>k)|(w<<(P-k)))&FULL


def successors(pair):
    c,d=pair
    if (c|d).bit_count()%2: return []
    word=0;bit=0
    for t in range(P-1):
        bit^=((c|d)>>t)&1;word|=bit<<(t+1)
    return [(word,c),(word^FULL,c)]


def valid(u,c,d):
    return all(((u>>((t+1)%P))&1)==
               (((u>>t)&1)^(((c>>t)&1)|((d>>t)&1))) for t in range(P))


def sccs(adj):
    seen=set();order=[]
    for v in adj:
        if v in seen:continue
        work=[(v,False)]
        while work:
            v,done=work.pop()
            if done:order.append(v);continue
            if v in seen:continue
            seen.add(v);work.append((v,True))
            work.extend((w,False) for w in adj[v] if w not in seen)
    rev={v:[] for v in adj}
    for v in adj:
        for w in adj[v]:rev[w].append(v)
    seen=set();result=[]
    for v in reversed(order):
        if v in seen:continue
        part=set();work=[v];seen.add(v)
        while work:
            w=work.pop();part.add(w)
            for z in rev[w]:
                if z not in seen:seen.add(z);work.append(z)
        result.append(part)
    return result


def gf4mul(a,b):
    out=0
    for _ in range(2):
        if b&1:out^=a
        b>>=1;a<<=1
        if a&4:a^=7
    return out


def gf4trace(a):return a^gf4mul(a,a)


def triple(x):
    return x[0]^x[1]^x[2],x[0]^gf4mul(2,x[1])^gf4mul(3,x[2])


def algebra_controls():
    for a in itertools.product(range(2),repeat=3):
        d,z=triple(a)
        assert tuple(d^gf4trace(gf4mul(alpha,z)) for alpha in (1,3,2))==a
        for b in itertools.product(range(2),repeat=3):
            e,w=triple(b)
            got=triple(tuple(x|y for x,y in zip(a,b)))
            pred=(d^e^(d&e)^gf4trace(gf4mul(z,gf4mul(w,w))),
                  gf4mul(1^e,z)^gf4mul(1^d,w)^gf4mul(gf4mul(z,w),gf4mul(z,w)))
            assert got==pred,(a,b,got,pred)
    # CRT projector and integration inverse, on all4096 temporal words.
    for w in range(1<<P):
        odd=rot(w,4)^rot(w,8)
        assert (odd==0)==(rot(w,4)==w)
        assert rot(odd,4)^rot(odd,8)==odd
        inv=rot(odd,4)^rot(odd,5)^rot(odd,6)^rot(odd,7)
        assert rot(inv,1)^inv==odd
    print(json.dumps({'algebra':'PASS','OR_triples':64,'CRT_words':4096}),flush=True)


def main():
    path=Path(os.environ['PARITY_KIT'])/'lean/Ruliology/CellularAutomata/Rule30MovingWaves.lean'
    source=path.read_text();sha=hashlib.sha256(path.read_bytes()).hexdigest()
    assert sha==KIT_SHA,(sha,KIT_SHA)
    profiles=[]
    for name in ('zeroProfiles','oneProfiles'):
        text=re.search(r'def '+name+r' : List Nat :=\s*\[([^]]+)\]',source)[1]
        profiles.append([int(s) for s in text.split(',')]);assert len(profiles[-1])==34
    seam=[]
    for a,b,q,r in itertools.product(range(2),range(2),range(P),range(P)):
        left=[rot(w,q) for w in profiles[a]]
        right=[rot(w,r) for w in profiles[b]]
        joined=left+right
        failures=sum(not valid(joined[i],joined[i+1],joined[i+2]) for i in (32,33))
        seam.append({'bits':[a,b],'phases':[q,r],'bad_column_equations':failures})
        if q==r:assert not failures
    root=(profiles[0][0],profiles[0][1])
    starts={tuple(rot(w,t) for w in root) for t in range(P)}
    adj={};seen=set(starts);work=deque(starts)
    while work:
        v=work.popleft();adj[v]=successors(v)
        for w in adj[v]:
            assert valid(w[0],*v)
            if w not in seen:
                seen.add(w);assert len(seen)<=4096,'FIXED_NODE_CAP';work.append(w)
    comps=sccs(adj)
    cyclic=[c for c in comps if len(c)>1 or any(v in adj[v] for v in c)]
    comp=next(c for c in cyclic if root in c)
    temporal=[]
    for t in range(P):
        c={tuple(rot(w,t) for w in v) for v in comp}
        assert c in cyclic
        temporal.append(c)
    branches=sorted(v for v in comp if len([w for w in adj[v] if w in comp])>1)
    returns=[]
    for b in branches:
        for w in adj[b]:
            if w not in comp:continue
            path=[b,w]
            while w not in branches:
                nxt=[z for z in adj[w] if z in comp]
                assert len(nxt)==1
                w=nxt[0];path.append(w);assert len(path)<=100
            returns.append({'start':b,'end':w,'length':len(path)-1,'path':path})
    period_counts={}
    for v in comp:
        least=next(t for t in range(1,P+1) if all(rot(w,t)==w for w in v))
        period_counts[least]=period_counts.get(least,0)+1
    summary={'generated_nodes':len(adj),'generated_edges':sum(map(len,adj.values())),
             'cyclic_components':sorted([len(c) for c in cyclic]),'root':root,
             'root_component_nodes':len(comp),'root_component_edges':sum(w in comp for v in comp for w in adj[v]),
             'branch_states':branches,'return_edges':[{k:v for k,v in x.items() if k!='path'} for x in returns],
             'temporal_component_orbit':next(t for t in range(1,P+1) if temporal[t%P]==comp),
             'temporal_half_shift_fixed_vertices':sum(all(rot(w,6)==w for w in v) for v in comp),
             'pair_least_period_counts':period_counts,
             'mixed_phase_seams_allowed':[(x['bits'],x['phases']) for x in seam if x['phases'][0]!=x['phases'][1] and not x['bad_column_equations']],
             'chaos_048':[(x['bits'],x['phases'],x['bad_column_equations']) for x in seam if all(t in (0,4,8) for t in x['phases'])]}
    out=Path(os.environ['CAPPED_OUT'])
    (out/'period12-graph.json').write_text(json.dumps({'adj':[[v,ws] for v,ws in adj.items()],
          'root_component':sorted(comp),'time_components':[sorted(c) for c in temporal],
          'returns':returns,'seams':seam,'summary':summary},indent=2)+'\n')
    print(json.dumps(summary),flush=True)
    algebra_controls()
    print('PERIOD12_EXTRACTION_COMPLETE',flush=True)


if __name__=='__main__':main()
